SELECT CASE WHEN c.credit_limit >= 15100 THEN 'high' WHEN c.credit_limit >= 3800 THEN 'mid' ELSE 'low' END AS credit_limit_bucket, COUNT(CASE WHEN s.country = 'UK' THEN 1 END) AS uk_count, MAX(s.started_at) AS latest_started_at FROM sessions s JOIN customers c ON s.customer_id = c.id GROUP BY CASE WHEN c.credit_limit >= 15100 THEN 'high' WHEN c.credit_limit >= 3800 THEN 'mid' ELSE 'low' END
